/* ========================================================
   🎛️ 群聊成员备注开关 (高级自选功能)
   ======================================================== */
:root {
    /* 👇 在这里切换群成员备注的显示状态！
       👉 填 flex : 显示备注（气泡下沉，适合偶尔单发的群）
       👉 填 none : 隐藏备注（只留头像+气泡，完美齐平，极度干净！） */
    --show-group-nickname: none;   
}

/* 5. 备注名字排版（由上面的开关全局控制） */
.grp-sender-row {
    display: var(--show-group-nickname) !important;  /* 👈 核心：监听变量开关 */
    margin-bottom: 3px !important;       
