  max-width: var(--img-photo-max-w) !important;
  max-height: var(--img-photo-max-h) !important;
  width: auto !important;
  height: auto !important;
  object-fit: contain !important;
  border-radius: calc(var(--img-card-radius) - var(--img-card-pad)) !important;
  box-shadow: none !important;
}
