/* 图片:固定比例 + 后两层用图床图片 */
:root {
  --img-w: 160px;          /* 实体图宽度 */
  --img-ratio: 3 / 4;      /* 4:3 横图;想要竖图就改成 3 / 4 */
  --st-r: 16px;            /* 圆角 */

  --st-gap1: 9px;          /* 第二层往右露出多少 */
  --st-gap2: 18px;         /* 第三层往右露出多少 */
  --st-in1: 8px;           /* 第二层上下各缩进多少 */
  --st-in2: 16px;          /* 第三层上下各缩进多少 */

  /* ★ 把两个链接换成你图床里的图 */

  --st-img1: url("https://imgbed.heliar.top/i/HPLqCkpwxlWeZW0k_IMG_0399.jpeg");
  --st-img2: url("https://imgbed.heliar.top/i/XKCH-a3_6FymY_Ft_IMG_0397.jpeg");

  --st-f1: none;
  --st-f2: none;

}
body.dark-mode {
  --st-f1: grayscale(0.5) blur(1.5px) brightness(0.6);
  --st-f2: grayscale(0.9) blur(2.5px) brightness(0.45);
}

/* 实体图卡片:固定大小 */
.msg-image-wrapper,
.msg-image-card {
  position: relative !important;
  isolation: isolate !important;
  width: var(--img-w) !important;
  max-width: 100% !important;
  height: auto !important;
  aspect-ratio: var(--img-ratio) !important;
  box-shadow: none !important;
  border-radius: var(--st-r) !important;
  margin: 0 calc(var(--st-gap2) + 2px) 0 0 !important;
}
body .chat-detail-screen .msg-image-wrapper > *,
body .chat-detail-screen .msg-image-card > * {
  width: 100% !important;
  height: 100% !important;
}
body .chat-detail-screen .msg-image-wrapper img,
body .chat-detail-screen .msg-image-card img {
  width: 100% !important;
  height: 100% !important;
  max-width: none !important;
  max-height: none !important;
  object-fit: cover !important;
  border-radius: var(--st-r) !important;
}

/* 后两层 */
.msg-image-wrapper::before,
.msg-image-card::before,
.msg-image-wrapper::after,
.msg-image-card::after {
  content: "" !important;
  display: block !important;
  position: absolute !important;
  border-radius: var(--st-r) !important;
  background-size: cover !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  pointer-events: none !important;
}
.msg-image-wrapper::before,
.msg-image-card::before {
  top: var(--st-in1) !important;
  bottom: var(--st-in1) !important;
  left: var(--st-gap1) !important;
  right: calc(-1 * var(--st-gap1)) !important;
  background-image: var(--st-img1) !important;
  filter: var(--st-f1) !important;
  z-index: -1 !important;
}
.msg-image-wrapper::after,
.msg-image-card::after {
  top: var(--st-in2) !important;
  bottom: var(--st-in2) !important;
  left: var(--st-gap2) !important;
  right: calc(-1 * var(--st-gap2)) !important;
  background-image: var(--st-img2) !important;
  filter: var(--st-f2) !important;
  z-index: -2 !important;
}
/* 实体图:盖过表情包的 110px 限制,并给固定高度 */
:root { --img-h: calc(var(--img-w) * 4 / 3); }   /* 3:4 竖图,宽 160 → 高约 213 */

body .chat-detail-screen .msg-image-wrapper,
body .chat-detail-screen .msg-image-card {
  width: var(--img-w) !important;
  height: var(--img-h) !important;
}

body .chat-detail-screen .bubble-me-custom:has(img) .msg-image-wrapper img,
body .chat-detail-screen .bubble-them-custom:has(img) .msg-image-wrapper img,
body .chat-detail-screen .bubble-me-custom:has(img) .msg-image-card img,
body .chat-detail-screen .bubble-them-custom:has(img) .msg-image-card img {
  width: 100% !important;
  height: 100% !important;
  max-width: none !important;
  max-height: none !important;
  object-fit: cover !important;
  border-radius: var(--st-r) !important;
}

/* 视频卡:封面保持原比例,不被图片缩小规则影响 */
body .chat-detail-screen .bubble-me-custom .msg-video-card img,
body .chat-detail-screen .bubble-them-custom .msg-video-card img,
body .chat-detail-screen .bubble-me-custom .msg-video-card video,
body .chat-detail-screen .bubble-them-custom .msg-video-card video,
body .chat-detail-screen .bubble-me-custom .msg-video-card canvas,
body .chat-detail-screen .bubble-them-custom .msg-video-card canvas {
  width: 100% !important;
  height: 100% !important;
  max-width: none !important;
  max-height: none !important;
  object-fit: cover !important;
  border-radius: inherit !important;
}

/* 转账卡片:更浅 + 文字更浅 */
:root {
  --tf-top: #faf3f6;     /* 上半:更浅的灰粉 */
  --tf-deep: #d8c0cc;    /* 下半 / 图标底 / 边框 */
  --tf-text: #bfa0b0;    /* 上半文字(浅) */
  --tf-radius: 4px;

  --transfer-card-bg: #faf3f6;
  --transfer-card-border: 1.5px solid #d8c0cc;
  --transfer-card-radius: 4px;
  --transfer-icon-bg: #d8c0cc;
  --transfer-amount-color: #bfa0b0;
  --transfer-success-card-bg: #faf3f6;
  --transfer-success-card-border: 1.5px solid #d8c0cc;
  --transfer-success-icon-bg: #d8c0cc;
  --transfer-success-label-color: #bfa0b0;
  --transfer-rejected-card-bg: #faf3f6;
  --transfer-rejected-card-border: 1.5px dashed #d8c0cc;
  --transfer-rejected-label-color: #d6c6ce;
  --transfer-expired-card-bg: #faf3f6;
  --transfer-expired-card-border: 1.5px dashed #d8c0cc;
  --transfer-expired-label-color: #d6c6ce;
}

.chat-detail-screen .msg-transfer-card {
  border-radius: var(--tf-radius) !important;
}
.chat-detail-screen .msg-transfer-card .msg-transfer-amount {
  color: #bfa0b0 !important;
  -webkit-text-fill-color: #bfa0b0 !important;
}

/* ============================================================
   补丁:粘贴到你整份 CSS 的【最末尾】
   ① 带引用的回复气泡恢复显示
   ② 引用里的图片/表情包/视频缩略图对准折线
   ============================================================ */

/* ------------------------------------------------------------
   ① 恢复带引用的气泡
   原因:文件末尾那段「表情包去气泡」没有排除引用块,
        引用里的缩略图也是 <img>,于是整个回复气泡被当成表情包变透明。
   这里把「里面带引用块」的气泡重新画回来(尾巴也恢复)。
   ------------------------------------------------------------ */
body .chat-detail-screen .bubble-me-custom:has(.msg-reply-block-detached, .msg-reply-block, [class*="msg-reply-detached"]) {
  background: var(--me-bg) !important;
  padding: 5px 14px !important;
  border-radius: calc(23px * var(--k)) !important;
  min-width: 0 !important;
}
body .chat-detail-screen .bubble-them-custom:has(.msg-reply-block-detached, .msg-reply-block, [class*="msg-reply-detached"]) {
  background: var(--them-bg) !important;
  padding: 5px 14px !important;
  border-radius: calc(23px * var(--k)) !important;
  min-width: 0 !important;
}
/* 小尾巴(只有第一条/单条本来就有内容,这里只是取消被藏掉) */
body .chat-detail-screen .bubble-me-custom:has(.msg-reply-block-detached, .msg-reply-block, [class*="msg-reply-detached"])::after,
body .chat-detail-screen .bubble-them-custom:has(.msg-reply-block-detached, .msg-reply-block, [class*="msg-reply-detached"])::after {
  display: block !important;
}

/* ------------------------------------------------------------
   ② 引用里的图片/表情包/视频
   上一版没有出现信封和 To:,说明媒体那一层不是我以为的元素。
   这一版不再依赖里面的 class:直接把【引用外框】本身画成胶囊,
   信封+To: 画在胶囊最左边(原位置),缩略图在它后面,折线落在缩略图中心。
   ------------------------------------------------------------ */
:root {
  --q-media-pad: 14px;   /* 胶囊左右内边距(和文字胶囊一样) */
  --q-media-gap: 6px;    /* To: 和缩略图之间的距离 */
  --q-to-w: 41px;        /* 「信封+To:」占的宽度;折线没对准缩略图就微调这个 */
}

/* 外框 = 只有「信封+To:」和缩略图,没有灰色气泡底 */
body .chat-detail-screen .msg-reply-block-detached:has(img, video, canvas) {
  --q-hook-in: calc(var(--q-media-pad) + var(--q-to-w) + var(--q-media-gap) + var(--rq-img) / 2);

  display: flex !important;
  align-items: center !important;
  justify-content: flex-start !important;
  gap: var(--q-media-gap) !important;
  box-sizing: border-box !important;
  width: 0 !important;
  min-width: calc(100% + var(--q-hook-w) + var(--q-hook-in)) !important;
  height: calc(var(--rq-img) + 14px) !important;
  padding: 6px var(--q-media-pad) 6px calc(var(--q-media-pad) + var(--q-to-w) + var(--q-media-gap)) !important;
